    // Initialize next_pos and prev_pos
    for (int i = 0; i < n; i++) {
        for (int c = 0; c < 26; c++) {
            prev_pos[i][c] = -1;
            next_pos[i][c] = -1;
        }
    }

    // Fill prev_pos
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            for (int c = 0; c < 26; c++)
                prev_pos[i][c] = prev_pos[i-1][c];
        }
        prev_pos[i][s[i] - 'a'] = i;
    }

    // Fill next_pos
    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) {
            for (int c = 0; c < 26; c++)
                next_pos[i][c] = next_pos[i+1][c];
        }
        next_pos[i][s[i] - 'a'] = i;
    }

    // DP for length 1
    for (int i = 0; i < n; i++)
        dp[i][i] = 1;

    // DP for length >= 2
    for (int len = 2; len <= n; len++) {
