#define MOD 1000000007LL

static long long mod_add(long long a, long long b) {
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}

static long long mod_sub(long long a, long long b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

int main() {
    char *s = (char *)malloc(1000005);
    if (!fgets(s, 1000005, stdin)) return 0;

    int n = strlen(s);
    while (n > 0 && (s[n - 1] == '\n' || s[n - 1] == '\r')) s[--n] = '\0';

    if (n == 0) {
        printf("0\n");
        free(s);
        return 0;
    }

    int *nextPos = (int *)malloc(sizeof(int) * n * 26);
    int *prevPos = (int *)malloc(sizeof(int) * n * 26);

    int last[26];
    for (int c = 0; c < 26; c++) last[c] = -1;
    for (int i = 0; i < n; i++) {
        for (int c = 0; c < 26; c++) prevPos[i * 26 + c] = last[c];
        last[s[i] - 'a'] = i;
    }

    for (int c = 0; c < 26; c++) last[c] = n;
    for (int i = n - 1; i >= 0; i--) {
        for (int c = 0; c < 26; c++) nextPos[i * 26 + c] = last[c];
        last[s[i] - 'a'] = i;
    }

    long long *dp = (long long *)malloc(sizeof(long long) * n * n);
    #define DP(i,j) dp[(long long)(i) * n + (j)]

    for (int i = 0; i < n; i++) DP(i, i) = 1;

    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;

            if (s[i] != s[j]) {
                long long val = DP(i + 1, j);
                val = mod_add(val, DP(i, j - 1));
                val = mod_sub(val, DP(i + 1, j - 1));
                DP(i, j) = val;
            } else {
                int c = s[i] - 'a';
                int l = nextPos[i * 26 + c];
                int r = prevPos[j * 26 + c];

                long long mid = (i + 1 <= j - 1) ? DP(i + 1, j - 1) : 0;

                if (l > r) {
                    DP(i, j) = (2 * mid + 2) % MOD;
                } else if (l == r) {
                    DP(i, j) = (2 * mid + 1) % MOD;
                } else {
                    long long sub = (l + 1 <= r - 1) ? DP(l + 1, r - 1) : 0;
                    long long val = (2 * mid) % MOD;
                    val = mod_sub(val, sub);
                    DP(i, j) = val;
                }
            }
        }
    }

    printf("%lld\n", DP(0, n - 1) % MOD);

    free(dp);
    free(nextPos);
    free(prevPos);
    free(s);
    return 0;
}

