    for (int i = 0; i < n; ++i) {
        last[S[i] - 'a'] = i;
        prevPos[i] = last;
    }

    // dp[l][r] = number of distinct palindromic subsequences in S[l..r]
    vector<vector<int>> dp(n, vector<int>(n, 0));

    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
