public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        if (s == null || s.isEmpty()) {
            System.out.println(0);
            return;
        }

        int n = s.length();
        char[] a = s.toCharArray();

        // prev[i] = previous position of a[i], or -1
        int[] prev = new int[n];
        int[] last = new int[26];
        Arrays.fill(last, -1);
        for (int i = 0; i < n; i++) {
            int c = a[i] - 'a';
            prev[i] = last[c];
            last[c] = i;
        }

        // next[i] = next position of a[i], or n
        int[] next = new int[n];
        Arrays.fill(last, n);
        for (int i = n - 1; i >= 0; i--) {
            int c = a[i] - 'a';
            next[i] = last[c];
            last[c] = i;
        }

        // dp[i][j] = number of distinct palindromic subsequences in s[i..j]
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) dp[i][i] = 1;

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;

                if (a[i] != a[j]) {
                    dp[i][j] = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1];
                } else {
                    int low = next[i];
                    int high = prev[j];

                    if (low > high) {
                        // no same char inside
                        dp[i][j] = 2 * dp[i + 1][j - 1] + 2;
                    } else if (low == high) {
                        // exactly one same char inside
                        dp[i][j] = 2 * dp[i + 1][j - 1] + 1;
                    } else {
                        // more than one same char inside
                        dp[i][j] = 2 * dp[i + 1][j - 1] - dp[low + 1][high - 1];
                    }
                }

                dp[i][j] %= MOD;
                if (dp[i][j] < 0) dp[i][j] += MOD;
            }
        }

        System.out.println(dp[0][n - 1] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
